// bot.mjs: decides whether an SMS appointment reminder may go out to a patient right now.
// Pure function of (user, now). No state, no network, no reliance on the machine's time zone.

// Quiet hours are judged on the patient's local wall clock.
const WINDOW_START_HOUR = 8; // inclusive: texts may go out from 08:00:00.000 local
const WINDOW_END_HOUR = 21; // exclusive: no texts from 21:00:00.000 local

// E.164: "+", a non-zero country code digit, then 7 to 14 more digits.
const E164 = /^\+[1-9]\d{7,14}$/;

/**
 * @param {{ id?: string, phone: string, timezone: string | null }} user
 * @param {Date} now
 * @returns {{ allowed: boolean, reason: string, nextAllowedAt: Date | null }}
 */
export function checkSms(user, now) {
  // Programmer errors throw, so the scheduler fails loudly instead of silently sending or holding.
  if (user === null || typeof user !== 'object') {
    throw new TypeError('checkSms: user must be an object');
  }
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    throw new TypeError('checkSms: now must be a valid Date');
  }

  // Data problems hold the text. There is no known time to retry, so nextAllowedAt is null.
  if (typeof user.phone !== 'string' || !E164.test(user.phone)) {
    return held(
      'The phone number is not a valid international number (expected a "+", country code and digits), so the text cannot be delivered.',
      null,
    );
  }

  const timeZone = user.timezone;
  if (!isKnownTimeZone(timeZone)) {
    const shown = timeZone == null ? 'not set' : `"${timeZone}"`;
    return held(
      `The patient's time zone is ${shown}, which is not a recognised time zone, so their local quiet hours cannot be checked. The text is held until a valid time zone is set.`,
      null,
    );
  }

  const local = wallClock(now, timeZone);
  if (local.hour >= WINDOW_START_HOUR && local.hour < WINDOW_END_HOUR) {
    return {
      allowed: true,
      reason: `It is ${hhmm(local)} for the patient in ${timeZone}, inside the ${WINDOW_START_HOUR}:00 to ${WINDOW_END_HOUR}:00 texting window.`,
      nextAllowedAt: null,
    };
  }

  // Before 08:00 the window opens later today. From 21:00 on it opens tomorrow.
  const opensToday = local.hour < WINDOW_START_HOUR;
  const dayOffset = opensToday ? 0 : 1;
  const nextDay = new Date(Date.UTC(local.year, local.month - 1, local.day + dayOffset));
  const nextAllowedAt = instantOfLocalTime(
    timeZone,
    nextDay.getUTCFullYear(),
    nextDay.getUTCMonth(),
    nextDay.getUTCDate(),
    WINDOW_START_HOUR,
  );

  return held(
    `It is ${hhmm(local)} for the patient in ${timeZone}. Reminder texts go out only from ${WINDOW_START_HOUR}:00 to ${WINDOW_END_HOUR}:00 local time, so this one is held until ${opensToday ? 'today' : 'tomorrow'} at ${WINDOW_START_HOUR}:00 local time.`,
    nextAllowedAt,
  );
}

function held(reason, nextAllowedAt) {
  return { allowed: false, reason, nextAllowedAt };
}

function isKnownTimeZone(timeZone) {
  if (typeof timeZone !== 'string' || timeZone.trim() === '') return false;
  try {
    new Intl.DateTimeFormat('en-US', { timeZone });
    return true;
  } catch {
    return false;
  }
}

// Wall-clock fields of an instant as seen in the given IANA zone.
function wallClock(instant, timeZone) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    hourCycle: 'h23',
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
    hour: 'numeric',
    minute: 'numeric',
    second: 'numeric',
  }).formatToParts(instant);
  const field = (type) => Number(parts.find((part) => part.type === type).value);
  return {
    year: field('year'),
    month: field('month'),
    day: field('day'),
    hour: field('hour'),
    minute: field('minute'),
    second: field('second'),
  };
}

// UTC offset in ms of the zone at a whole-second instant (ms since epoch).
function offsetMs(instantMs, timeZone) {
  const w = wallClock(new Date(instantMs), timeZone);
  const wallAsUtc = Date.UTC(w.year, w.month - 1, w.day, w.hour, w.minute, w.second);
  return wallAsUtc - instantMs;
}

// The instant at which the zone's wall clock first reads hour:00:00 on the given date.
function instantOfLocalTime(timeZone, year, monthIndex, day, hour) {
  const wallMs = Date.UTC(year, monthIndex, day, hour);
  const first = wallMs - offsetMs(wallMs, timeZone);
  // Second pass, because the offset at the first guess can differ from the offset at the answer.
  return new Date(wallMs - offsetMs(first, timeZone));
}

function hhmm(local) {
  const pad = (n) => String(n).padStart(2, '0');
  return `${pad(local.hour)}:${pad(local.minute)}`;
}

// Run with: node --test bot.test.mjs
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { checkSms } from './bot.mjs';

const chicago = (timezone = 'America/Chicago') => ({ id: 'u_123', phone: '+13125550142', timezone });

test('allowed mid-day in Chicago', () => {
  const r = checkSms(chicago(), new Date('2026-10-23T17:00:00Z')); // 12:00 CDT
  assert.equal(r.allowed, true);
  assert.equal(r.nextAllowedAt, null);
  assert.equal(typeof r.reason, 'string');
});

test('window opens exactly at 08:00 local, not a moment earlier', () => {
  const before = checkSms(chicago(), new Date('2026-10-23T12:59:59.999Z')); // 07:59:59.999 CDT
  assert.equal(before.allowed, false);
  assert.equal(before.nextAllowedAt.toISOString(), '2026-10-23T13:00:00.000Z');

  const at = checkSms(chicago(), new Date('2026-10-23T13:00:00.000Z')); // 08:00:00.000 CDT
  assert.equal(at.allowed, true);
});

test('window closes at 21:00 local and reopens next morning', () => {
  const late = checkSms(chicago(), new Date('2026-10-24T01:59:59.999Z')); // 20:59:59.999 CDT
  assert.equal(late.allowed, true);

  const closed = checkSms(chicago(), new Date('2026-10-24T02:00:00.000Z')); // 21:00 CDT
  assert.equal(closed.allowed, false);
  assert.equal(closed.nextAllowedAt.toISOString(), '2026-10-24T13:00:00.000Z'); // 08:00 CDT next day
});

test('standard time (CST) offset is used in winter', () => {
  const r = checkSms(chicago(), new Date('2026-01-15T11:00:00Z')); // 05:00 CST
  assert.equal(r.allowed, false);
  assert.equal(r.nextAllowedAt.toISOString(), '2026-01-15T14:00:00.000Z'); // 08:00 CST
});

test('held across the US DST change (2026-11-01, CDT ends at 02:00)', () => {
  const r = checkSms(chicago(), new Date('2026-11-01T05:30:00Z')); // 00:30 CDT
  assert.equal(r.allowed, false);
  assert.equal(r.nextAllowedAt.toISOString(), '2026-11-01T14:00:00.000Z'); // 08:00 CST
});

test('half-hour zone: India (UTC+05:30)', () => {
  const kolkata = chicago('Asia/Kolkata');
  const early = checkSms(kolkata, new Date('2026-10-23T02:00:00Z')); // 07:30 IST
  assert.equal(early.allowed, false);
  assert.equal(early.nextAllowedAt.toISOString(), '2026-10-23T02:30:00.000Z'); // 08:00 IST

  const night = checkSms(kolkata, new Date('2026-10-23T15:30:00Z')); // 21:00 IST
  assert.equal(night.allowed, false);
  assert.equal(night.nextAllowedAt.toISOString(), '2026-10-24T02:30:00.000Z');
});

test('half-hour zone with DST: Australia/Adelaide (+10:30 in October)', () => {
  const r = checkSms(chicago('Australia/Adelaide'), new Date('2026-10-22T20:30:00Z')); // 07:00 ACDT
  assert.equal(r.allowed, false);
  assert.equal(r.nextAllowedAt.toISOString(), '2026-10-22T21:30:00.000Z'); // 08:00 ACDT
});

test('nextAllowedAt is always a future instant when held', () => {
  const now = new Date('2026-10-23T09:00:00Z');
  for (const tz of ['Europe/London', 'Asia/Tokyo', 'Pacific/Chatham', 'America/Anchorage']) {
    const r = checkSms(chicago(tz), now);
    if (!r.allowed) assert.ok(r.nextAllowedAt.getTime() > now.getTime(), tz);
  }
});

test('missing, null, empty or unknown time zone is held with null retry time', () => {
  const now = new Date('2026-10-23T17:00:00Z');
  for (const timezone of [null, undefined, '', '   ', 'Mars/Olympus', 'Chicago']) {
    const r = checkSms({ id: 'u', phone: '+13125550142', timezone }, now);
    assert.equal(r.allowed, false, String(timezone));
    assert.equal(r.nextAllowedAt, null, String(timezone));
    assert.match(r.reason, /time zone/);
  }
});

test('malformed phone is held with null retry time', () => {
  const now = new Date('2026-10-23T17:00:00Z');
  for (const phone of ['3125550142', '+0123', '', null, 42]) {
    const r = checkSms({ id: 'u', phone, timezone: 'America/Chicago' }, now);
    assert.equal(r.allowed, false, String(phone));
    assert.equal(r.nextAllowedAt, null);
  }
});

test('result does not depend on the machine time zone', () => {
  const r = checkSms(chicago(), new Date('2026-10-23T12:59:59.999Z'));
  assert.equal(r.nextAllowedAt.toISOString(), '2026-10-23T13:00:00.000Z');
});

test('invalid arguments throw', () => {
  assert.throws(() => checkSms(chicago(), new Date('nope')), TypeError);
  assert.throws(() => checkSms(chicago(), '2026-10-23'), TypeError);
  assert.throws(() => checkSms(null, new Date()), TypeError);
});

